CREATE OR REPLACE FUNCTION private.google_sheets_checked_ticket_v1(p_ticket_id uuid, p_workspace_id uuid)
 RETURNS private.google_sheets_read_tickets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t private.google_sheets_read_tickets;
begin
 perform private.google_sheets_privacy_open_v1(p_workspace_id);
 select * into t from private.google_sheets_read_tickets where id=p_ticket_id and workspace_id=p_workspace_id;
 if t.id is null or t.expires_at<=clock_timestamp() or t.epoch<>(select epoch from private.google_sheets_privacy_epochs where workspace_id=p_workspace_id) then
  raise exception 'google_sheets_read_ticket_stale' using errcode='40001'; end if;
 perform private.google_sheets_ticket_actor_v1(p_workspace_id,t.actor_id);
 return t;
end $function$

CREATE OR REPLACE FUNCTION private.guard_trusted_derived_run_transition_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.agent_type in (
    'business_health_explanation_v1','finding_explanation_v1','intelligence_briefing_v1'
  ) and old.status='processing' and new.status in ('completed','failed') then
    perform 1 from private.trusted_derived_run_commits as claim
      where claim.run_id=old.id and claim.workspace_id=old.workspace_id
        and claim.transition=new.status
        and claim.transaction_id=txid_current()
        and new.created_by is not distinct from old.created_by
        and new.agent_type=old.agent_type and new.workspace_id=old.workspace_id
        and new.input_json=old.input_json
      for share;
    if not found then
      raise exception 'trusted_derived_run_commit_required' using errcode='42501';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_trusted_derived_run_v1(p_workspace_id uuid, p_run_id uuid, p_actor_id uuid, p_session_id uuid, p_read_ticket_id uuid, p_agent_type text, p_output_json jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.ai_agent_runs; t private.google_sheets_read_tickets;
begin
  if p_agent_type not in (
    'business_health_explanation_v1','finding_explanation_v1','intelligence_briefing_v1'
  ) or jsonb_typeof(p_output_json) is distinct from 'object'
    or octet_length(p_output_json::text)>2097152
    or p_output_json->>'contractId' is distinct from p_agent_type then
    raise exception 'trusted_derived_output_invalid' using errcode='22023';
  end if;
  perform private.require_live_actor_session_v1(
    p_workspace_id,p_actor_id,p_session_id,
    array['owner','admin','manager','staff','viewer']
  );
  t:=private.google_sheets_checked_ticket_v1(p_read_ticket_id,p_workspace_id);
  if t.actor_id is distinct from p_actor_id or not t.bound then
    raise exception 'trusted_derived_read_ticket_denied' using errcode='42501';
  end if;
  select * into r from public.ai_agent_runs
    where id=p_run_id and workspace_id=p_workspace_id
      and agent_type=p_agent_type and created_by=p_actor_id
      and status='processing' and trusted_source
      and archived_at is null and deleted_at is null
    for update;
  if not found
    or r.input_json->>'workflow' is distinct from p_agent_type
    or r.input_json->>'google_sheets_read_ticket_id' is distinct from p_read_ticket_id::text
    or (r.google_sheets_read_ticket_id is not null
      and r.google_sheets_read_ticket_id<>p_read_ticket_id) then
    raise exception 'trusted_derived_run_changed' using errcode='42501';
  end if;
  if p_agent_type in ('business_health_explanation_v1','finding_explanation_v1') then
    if r.input_json->>'fingerprint' is null
      or r.input_json->>'fingerprint' !~ '^[0-9a-f]{64}$'
      or p_output_json->>'fingerprint' is distinct from r.input_json->>'fingerprint'
      or p_output_json->>'contractVersion' is distinct from r.input_json->>'contract_version'
      or p_output_json->>'validatorVersion' is distinct from r.input_json->>'validator_version' then
      raise exception 'trusted_derived_output_identity_changed' using errcode='42501';
    end if;
  else
    if r.input_json->>'generation_key' is null
      or p_output_json->>'workspaceId' is distinct from p_workspace_id::text
      or p_output_json->>'briefingType' is distinct from r.input_json->>'briefing_type'
      or p_output_json->>'generationKey' is distinct from r.input_json->>'generation_key'
      or p_output_json->>'evidenceFingerprint'
        is distinct from r.input_json->>'evidence_fingerprint'
      or p_output_json->>'effectiveEvidenceFingerprint'
        is distinct from r.input_json->>'effective_evidence_fingerprint'
      or p_output_json->>'materialStateFingerprint'
        is distinct from r.input_json->>'material_state_fingerprint'
      or p_output_json->>'schemaVersion' is distinct from r.input_json->>'schema_version'
      or p_output_json->>'validatorVersion' is distinct from r.input_json->>'validator_version'
      or p_output_json->>'promptVersion' is distinct from r.input_json->>'prompt_version'
      or p_output_json->>'generationPolicyVersion'
        is distinct from r.input_json->>'generation_policy_version' then
      raise exception 'trusted_derived_output_identity_changed' using errcode='42501';
    end if;
  end if;
  insert into private.trusted_derived_run_commits(
    run_id,workspace_id,actor_id,read_ticket_id,transition,transaction_id
  ) values (p_run_id,p_workspace_id,p_actor_id,p_read_ticket_id,'completed',txid_current());
  update public.ai_agent_runs set output_json=p_output_json,status='completed',
    error_message=null,google_sheets_read_ticket_id=p_read_ticket_id,
    updated_at=clock_timestamp()
    where id=p_run_id and workspace_id=p_workspace_id;
  delete from private.trusted_derived_run_commits where run_id=p_run_id;
  return p_run_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.fail_trusted_derived_run_v1(p_workspace_id uuid, p_run_id uuid, p_actor_id uuid, p_session_id uuid, p_read_ticket_id uuid, p_agent_type text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.ai_agent_runs; t private.google_sheets_read_tickets;
begin
  if p_agent_type not in (
    'business_health_explanation_v1','finding_explanation_v1','intelligence_briefing_v1'
  ) then
    raise exception 'trusted_derived_type_invalid' using errcode='22023';
  end if;
  perform private.require_live_actor_session_v1(
    p_workspace_id,p_actor_id,p_session_id,
    array['owner','admin','manager','staff','viewer']
  );
  t:=private.google_sheets_checked_ticket_v1(p_read_ticket_id,p_workspace_id);
  if t.actor_id is distinct from p_actor_id or not t.bound then
    raise exception 'trusted_derived_read_ticket_denied' using errcode='42501';
  end if;
  select * into r from public.ai_agent_runs
    where id=p_run_id and workspace_id=p_workspace_id
      and agent_type=p_agent_type and created_by=p_actor_id
      and status='processing' and trusted_source
      and archived_at is null and deleted_at is null
    for update;
  if not found
    or r.input_json->>'workflow' is distinct from p_agent_type
    or r.input_json->>'google_sheets_read_ticket_id' is distinct from p_read_ticket_id::text then
    raise exception 'trusted_derived_run_changed' using errcode='42501';
  end if;
  insert into private.trusted_derived_run_commits(
    run_id,workspace_id,actor_id,read_ticket_id,transition,transaction_id
  ) values (p_run_id,p_workspace_id,p_actor_id,p_read_ticket_id,'failed',txid_current());
  update public.ai_agent_runs set status='failed',
    error_message=case p_agent_type
      when 'business_health_explanation_v1' then 'Business Health analysis generation failed.'
      when 'finding_explanation_v1' then 'Finding explanation generation failed.'
      else 'Intelligence Briefing generation failed.' end,
    updated_at=clock_timestamp()
    where id=p_run_id and workspace_id=p_workspace_id;
  delete from private.trusted_derived_run_commits where run_id=p_run_id;
  return p_run_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_google_sheets_read_context_v1(p_ticket_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t private.google_sheets_read_tickets; result jsonb; s jsonb; row_data jsonb; unattributed boolean:=false;
begin
 select * into t from private.google_sheets_read_tickets where id=p_ticket_id;
 if t.id is null then raise exception 'google_sheets_read_ticket_stale' using errcode='40001'; end if;
 t:=private.google_sheets_checked_ticket_v1(t.id,t.workspace_id);
 if not t.bound then raise exception 'google_sheets_read_ticket_unbound' using errcode='40001'; end if;
 result:=public.bind_google_sheets_read_v1(t.id,'[]');
 for s in select value from jsonb_array_elements(t.sources) where (exists(select 1 from private.google_sheets_source_root_links where workspace_id=t.workspace_id) or exists(select 1 from private.google_sheets_connection_root_links where workspace_id=t.workspace_id))
 and value->>'table'=any(array[
  'ai_agent_runs','reports','business_health_snapshots','vsi_exchanges','vsi_conversations','intelligence_card_lifecycle','intelligence_card_lifecycle_events','business_notes','business_memory_chunks','file_processing_jobs','file_uploads','kpi_settings']) loop
  execute format('select to_jsonb(x) from public.%I x where id=$1 and workspace_id=$2',s->>'table') into row_data using (s->>'id')::uuid,t.workspace_id;
  if row_data is null then raise exception 'google_sheets_read_source_changed' using errcode='40001'; end if;
  if s->>'table'='file_uploads' and private.google_sheets_unmaterialized_file_v1(
   row_data,t.workspace_id,(s->>'id')::uuid) then continue; end if;
  if s->>'table'='kpi_settings' and coalesce(row_data->>'classification_source','unknown')<>'luna' then continue; end if;
  if nullif(row_data->>'google_sheets_read_ticket_id','') is null and not exists(select 1 from private.google_sheets_derivation_roots
   where workspace_id=t.workspace_id and (table_name=s->>'table' or s->>'table'='file_uploads' and table_name='file_upload_analysis') and record_id=(s->>'id')::uuid) then unattributed:=true; end if;
 end loop;
 return result||jsonb_build_object('workspaceId',t.workspace_id,'containsGoogleSheets',jsonb_array_length(result->'connectionIds')>0,
  'hasUnattributedDerivedSources',unattributed);
end $function$

CREATE OR REPLACE FUNCTION public.vsi_mutate_v2(p_workspace_id uuid, p_actor_user_id uuid, p_action text, p_input jsonb, p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.require_live_actor_session_v1(
    p_workspace_id,p_actor_user_id,p_session_id,
    array['owner','admin','manager','staff','viewer']
  );
  return public.vsi_mutate_v1(
    p_workspace_id,p_actor_user_id,p_action,p_input
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.qbo_customer_require_owner_v1(p_actor uuid, p_session uuid, p_workspace uuid, p_entity uuid, p_require_entitlement boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_expires timestamptz;
  v_subscription public.customer_subscriptions;
begin
  if p_actor is null or p_session is null or p_workspace is null or p_entity is null then
    raise exception 'qbo_customer_owner_denied' using errcode = '42501';
  end if;
  perform 1 from public.workspaces where id = p_workspace for share;
  if not found then raise exception 'qbo_customer_owner_denied' using errcode = '42501'; end if;
  select s.not_after into v_expires from auth.sessions s
    join auth.users u on u.id = s.user_id
    where s.id = p_session and s.user_id = p_actor and u.deleted_at is null
      and (u.banned_until is null or u.banned_until <= clock_timestamp())
    for share of s, u;
  if not found or (v_expires is not null and v_expires <= clock_timestamp()) then
    raise exception 'qbo_customer_session_denied' using errcode = '42501';
  end if;
  perform 1 from public.workspace_members m where m.workspace_id = p_workspace
    and m.user_id = p_actor and m.role = 'owner' and m.status = 'active' for share;
  if not found then raise exception 'qbo_customer_owner_denied' using errcode = '42501'; end if;
  perform 1 from public.business_entities e where e.workspace_id = p_workspace
    and e.id = p_entity and e.status = 'active' for share;
  if not found then raise exception 'qbo_customer_entity_denied' using errcode = '42501'; end if;
  if not p_require_entitlement then return; end if;
  select s.* into v_subscription from public.customer_subscriptions s
    where s.workspace_id = p_workspace and s.billing_provider = 'stripe'
    order by s.created_at desc, s.id desc limit 1 for share;
  if found then
    if v_subscription.manually_activated or v_subscription.status not in ('active','trialing')
      or v_subscription.current_period_end is null or v_subscription.current_period_end <= clock_timestamp()
      or v_subscription.stripe_customer_id is null or v_subscription.stripe_subscription_id is null then
      raise exception 'qbo_customer_entitlement_denied' using errcode = '42501';
    end if;
  elsif not exists (select 1 from public.workspaces w
      join public.customer_subscriptions s on s.workspace_id = w.id
      where w.id = p_workspace and w.manually_unlocked and s.billing_provider = 'manual'
        and s.manually_activated and s.status in ('active','trialing')) then
    raise exception 'qbo_customer_entitlement_denied' using errcode = '42501';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.square_production_customer_require_owner_v1(p_actor_id uuid, p_session_id uuid, p_workspace_id uuid, p_business_entity_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare expires_at timestamptz; member_role text; member_status text; entity_status text; now_at timestamptz;
begin
  if p_actor_id is null or p_session_id is null or p_workspace_id is null then
    raise exception 'square_production_customer_owner_denied' using errcode='42501';
  end if;
  perform 1 from public.workspaces where id=p_workspace_id for share;
  if not found then raise exception 'square_production_customer_owner_denied' using errcode='42501'; end if;
  select s.not_after into expires_at from auth.sessions s
    join auth.users u on u.id=s.user_id
    where s.id=p_session_id and s.user_id=p_actor_id and u.deleted_at is null
      and (u.banned_until is null or u.banned_until<=clock_timestamp())
    for share of s,u;
  if not found then raise exception 'square_production_customer_owner_denied' using errcode='42501'; end if;
  select m.role,m.status into member_role,member_status from public.workspace_members m
    where m.user_id=p_actor_id and m.workspace_id=p_workspace_id for share;
  if not found then raise exception 'square_production_customer_owner_denied' using errcode='42501'; end if;
  if p_business_entity_id is not null then
    select e.status into entity_status from public.business_entities e
      where e.id=p_business_entity_id and e.workspace_id=p_workspace_id for share;
    if not found then raise exception 'square_production_customer_owner_denied' using errcode='42501'; end if;
  end if;
  now_at:=clock_timestamp();
  -- Supabase leaves not_after NULL when absolute session time-boxing is off.
  -- The exact live session/user binding above remains mandatory; finite
  -- expirations are enforced, and request JWT validity is checked by the host.
  if (expires_at is not null and expires_at<=now_at) or member_role<>'owner'
    or member_status<>'active' or (p_business_entity_id is not null and entity_status<>'active') then
    raise exception 'square_production_customer_owner_denied' using errcode='42501';
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.vsi_mutate_v1(p_workspace_id uuid, p_actor_user_id uuid, p_action text, p_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.role() is distinct from 'service_role' then raise exception 'vsi_server_only' using errcode='42501'; end if;
 perform private.google_sheets_privacy_open_v1(p_workspace_id);
 if nullif(p_input->>'conversationId','') is not null and not public.google_sheets_record_readable_v1(p_workspace_id,'vsi_conversations',(p_input->>'conversationId')::uuid) then raise exception 'google_sheets_source_expired' using errcode='55000'; end if;
 perform set_config('vaeroex.google_sheets_read_ticket_id',coalesce(p_input->>'readTicketId',''),true);
 return private.vsi_mutate_before_sheets_privacy_v1(p_workspace_id,p_actor_user_id,p_action,p_input-'readTicketId');
end $function$

CREATE OR REPLACE FUNCTION private.google_sheets_derivative_write_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t private.google_sheets_read_tickets; tid uuid; w uuid; n jsonb:=to_jsonb(new); old_data jsonb; sink_table text:=tg_table_name;
begin
 w:=(n->>'workspace_id')::uuid;
 if tg_table_name='file_uploads' then
  sink_table:='file_upload_analysis';
  if tg_op='UPDATE' and private.google_sheets_exact_delete_allowed_v1(w,sink_table,old.id,to_jsonb(old))
   and new.analysis_prompt is null and new.analysis_summary is null
   and new.metadata_json=private.google_sheets_file_metadata_without_analysis_v1(old.metadata_json)
   and (n-'analysis_prompt'-'analysis_summary'-'metadata_json'-'google_sheets_read_ticket_id'-'updated_at')=
    (to_jsonb(old)-'analysis_prompt'-'analysis_summary'-'metadata_json'-'google_sheets_read_ticket_id'-'updated_at') then return new; end if;
 end if;
 -- Fresh uploads and ordinary settings are user-supplied records. Their model
 -- generated fields use this same fence without blocking storage bookkeeping.
 if tg_table_name='file_uploads' and nullif(n->>'google_sheets_read_ticket_id','') is null
  and nullif(current_setting('vaeroex.google_sheets_read_ticket_id',true),'') is null
  and (tg_op='INSERT' and coalesce(n->>'analysis_summary','')='' or tg_op='UPDATE'
   and n->>'analysis_summary' is not distinct from to_jsonb(old)->>'analysis_summary'
   and not exists(select 1 from private.google_sheets_derivation_roots where workspace_id=w and table_name=sink_table and record_id=(n->>'id')::uuid)) then return new; end if;
 if tg_table_name='file_processing_jobs' and coalesce(n->>'job_type','') not in ('analyze','index')
  and nullif(n->>'google_sheets_read_ticket_id','') is null
  and nullif(current_setting('vaeroex.google_sheets_read_ticket_id',true),'') is null then return new; end if;
 if tg_table_name='file_uploads' and tg_op='UPDATE' and
  (n-'processing_status'-'processing_error'-'processed_at'-'index_status'-'index_error'-'indexed_at'-'indexed_chunk_count'-'import_status'-'imported_rows'-'updated_at')=
  (to_jsonb(old)-'processing_status'-'processing_error'-'processed_at'-'index_status'-'index_error'-'indexed_at'-'indexed_chunk_count'-'import_status'-'imported_rows'-'updated_at') then return new; end if;
 if tg_table_name='kpi_settings' and coalesce(n->>'classification_source','unknown')<>'luna'
  and nullif(n->>'google_sheets_read_ticket_id','') is null
  and nullif(current_setting('vaeroex.google_sheets_read_ticket_id',true),'') is null then return new; end if;
 if tg_op='UPDATE' then
  old_data:=to_jsonb(old);
  -- Lifecycle-only changes do not produce new Google-derived content.
  if (n-'archived_at'-'deleted_at'-'updated_at'-'status'-'error_message')=
     (old_data-'archived_at'-'deleted_at'-'updated_at'-'status'-'error_message') then return new; end if;
 end if;
 if not exists(select 1 from private.google_sheets_source_root_links where workspace_id=w) and not exists(select 1 from private.google_sheets_connection_root_links where workspace_id=w) then return new; end if;
 tid:=coalesce(nullif(current_setting('vaeroex.google_sheets_read_ticket_id',true),'')::uuid,
  nullif(n#>>'{card_snapshot_json,google_sheets_read_ticket_id}','')::uuid,
  nullif(n#>>'{source_metadata,google_sheets_read_ticket_id}','')::uuid,
  nullif(n->>'google_sheets_read_ticket_id','')::uuid,
  nullif(n#>>'{input_json,google_sheets_read_ticket_id}','')::uuid);
 t:=private.google_sheets_checked_ticket_v1(tid,w);
 if not t.bound then raise exception 'google_sheets_read_ticket_unbound' using errcode='40001'; end if;
 if (public.get_google_sheets_read_context_v1(tid)->>'hasUnattributedDerivedSources')::boolean then
  raise exception 'google_sheets_unattributed_source' using errcode='55000'; end if;
 -- A new empty ticket cannot relabel an existing legacy derived record as
 -- proven unrelated. Lifecycle-only updates above preserve its old ticket.
 if tg_op='UPDATE' and nullif(old_data->>'google_sheets_read_ticket_id','') is null
  and not exists(select 1 from private.google_sheets_derivation_roots where workspace_id=w and table_name=sink_table and record_id=(n->>'id')::uuid)
  and not (tg_table_name='file_uploads' and private.google_sheets_unmaterialized_file_v1(
   old_data,w,(n->>'id')::uuid))
  and not(tg_table_name='kpi_settings' and coalesce(old_data->>'classification_source','unknown')<>'luna') then
  raise exception 'google_sheets_unattributed_source' using errcode='55000'; end if;
 if exists(select 1 from jsonb_array_elements(t.sources) s join private.google_sheets_derivation_roots d
  on d.workspace_id=w and (d.table_name=s->>'table' or s->>'table'='file_uploads' and d.table_name='file_upload_analysis') and d.record_id=(s->>'id')::uuid
  join private.google_sheets_retention_roots r on r.id=d.root_id where r.erased_at is not null or r.expires_at<=clock_timestamp()) then
  raise exception 'google_sheets_source_expired' using errcode='55000'; end if;
 new.google_sheets_read_ticket_id:=tid;
 -- Union, never replacement: editing/copying an artifact cannot wash its lineage.
 insert into private.google_sheets_derivation_roots(workspace_id,table_name,record_id,root_id)
 select distinct w,sink_table,(n->>'id')::uuid,d.root_id from jsonb_array_elements(t.sources) s
 join private.google_sheets_derivation_roots d on d.workspace_id=w and (d.table_name=s->>'table' or s->>'table'='file_uploads' and d.table_name='file_upload_analysis') and d.record_id=(s->>'id')::uuid
 on conflict do nothing;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.vsi_mutate_before_sheets_privacy_v1(p_workspace_id uuid, p_actor_user_id uuid, p_action text, p_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.vsi_conversations; r public.vsi_requests; e public.vsi_exchanges; n public.business_notes;
 v_now timestamptz:=clock_timestamp(); v_note uuid; v_role text; v_count integer; v_spent numeric; v_reserved numeric; v_reserve numeric; v_budget numeric;
begin
 if coalesce((select auth.role()),'')<>'service_role' then raise exception 'vsi_server_only' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('vsi-actor:'||p_actor_user_id::text,0));
 perform pg_advisory_xact_lock(hashtextextended('vsi-workspace:'||p_workspace_id::text,0));
 select role::text into v_role from public.workspace_members where workspace_id=p_workspace_id and user_id=p_actor_user_id and status='active' for share;
 if not found then raise exception 'vsi_access_denied' using errcode='42501'; end if;
 if not private.workspace_billing_entitled_v1(p_workspace_id) and not exists(select 1 from private.platform_admin_subscription_exemptions where user_id=p_actor_user_id) then
   raise exception 'vsi_subscription_required' using errcode='42501';
 end if;
 if p_action='create' then
   insert into public.vsi_conversations(workspace_id,actor_user_id,actor_role,title) values(p_workspace_id,p_actor_user_id,v_role,left(coalesce(nullif(btrim(p_input->>'title'),''),'New chat'),120)) returning * into c;
   return to_jsonb(c);
 end if;
 if p_action='usage' then
   return jsonb_build_object('used',(select count(*) from public.vsi_requests where actor_user_id=p_actor_user_id and accepted_at>v_now-interval '24 hours' and status='completed'),
    'resetsAt',(select min(accepted_at)+interval '24 hours' from public.vsi_requests where actor_user_id=p_actor_user_id and accepted_at>v_now-interval '24 hours' and status='completed'),
    'spentUsd',(select coalesce(sum(cost_usd),0) from public.vsi_cost_events where workspace_id=p_workspace_id and occurred_at>=date_trunc('month',v_now at time zone 'UTC') at time zone 'UTC'),
    'reservedUsd',(select coalesce(sum(reservation_usd),0) from public.vsi_requests where workspace_id=p_workspace_id and status='pending'),
    'periodStart',date_trunc('month',v_now at time zone 'UTC') at time zone 'UTC');
 end if;
 select * into c from public.vsi_conversations where id=(p_input->>'conversationId')::uuid and workspace_id=p_workspace_id and actor_user_id=p_actor_user_id and actor_role=v_role for update;
 if not found then raise exception 'vsi_conversation_not_found' using errcode='42501'; end if;
 if p_action='rename' then
  update public.vsi_conversations set title=left(btrim(p_input->>'title'),120),updated_at=v_now where id=c.id returning * into c; return to_jsonb(c);
 elsif p_action='delete' then
  if exists(select 1 from public.vsi_requests where conversation_id=c.id and status='pending' and lease_until>v_now) then return jsonb_build_object('error','in_progress'); end if;
  delete from public.vsi_conversations where id=c.id; return jsonb_build_object('deleted',true);
 elsif p_action='continue' then
  if c.exchange_count<250 then return jsonb_build_object('error','thread_not_full'); end if;
  select * into c from public.vsi_conversations where parent_conversation_id=c.id and workspace_id=p_workspace_id and actor_user_id=p_actor_user_id;
  if found then return to_jsonb(c); end if;
  select * into c from public.vsi_conversations where id=(p_input->>'conversationId')::uuid;
  insert into public.vsi_conversations(workspace_id,actor_user_id,actor_role,title,parent_conversation_id,context_summary)
    values(p_workspace_id,p_actor_user_id,v_role,left(c.title||' (continued)',120),c.id,c.context_summary) returning * into c;
  return to_jsonb(c);
 elsif p_action='reserve' then
  select * into r from public.vsi_requests where workspace_id=p_workspace_id and actor_user_id=p_actor_user_id and request_id=(p_input->>'requestId')::uuid;
  if found and (r.question_hash<>p_input->>'questionHash' or r.conversation_id is distinct from c.id) then return jsonb_build_object('error','idempotency_conflict'); end if;
  if found and r.status='completed' then return jsonb_build_object('state','completed','request',to_jsonb(r)); end if;
  if found and r.status='pending' and r.lease_until>v_now then return jsonb_build_object('error','in_progress'); end if;
  -- A crashed call has unknown cost: charge its reservation conservatively,
  -- free its question slot, and permit an idempotent retry.
  insert into public.vsi_cost_events(request_id,workspace_id,actor_user_id,attempt,occurred_at,cost_usd,usage_json)
   select id,workspace_id,actor_user_id,attempt,started_at,reservation_usd,jsonb_build_object('status','expired','costEstimated',true,'estimatedCostUsd',reservation_usd)
   from public.vsi_requests where status='pending' and lease_until<=v_now and (actor_user_id=p_actor_user_id or workspace_id=p_workspace_id)
   on conflict(request_id,attempt) do nothing;
  update public.vsi_requests set status='failed',cost_usd=cost_usd+reservation_usd,reservation_usd=0,
   usage_json=usage_json||jsonb_build_array(jsonb_build_object('status','expired','costEstimated',true,'estimatedCostUsd',reservation_usd))
   where status='pending' and lease_until<=v_now and (actor_user_id=p_actor_user_id or workspace_id=p_workspace_id);
  if exists(select 1 from public.vsi_requests where actor_user_id=p_actor_user_id and status='pending') then return jsonb_build_object('error','in_progress'); end if;
  if (select count(*) from public.vsi_requests where workspace_id=p_workspace_id and status='pending')>=4 then return jsonb_build_object('error','workspace_busy'); end if;
  if c.exchange_count>=250 then return jsonb_build_object('error','thread_full'); end if;
  select count(*) into v_count from public.vsi_requests where actor_user_id=p_actor_user_id and status='completed' and accepted_at>v_now-interval '24 hours';
  if v_count>=100 then return jsonb_build_object('error','daily_limit'); end if;
  if (select count(*) from public.vsi_requests where actor_user_id=p_actor_user_id and started_at>v_now-interval '1 minute')>=10 then return jsonb_build_object('error','burst_limit'); end if;
  v_reserve:=(p_input->>'reserveUsd')::numeric; v_budget:=(p_input->>'monthlyBudgetUsd')::numeric;
  if v_reserve is null or v_reserve<=0 or v_reserve>5 or v_budget is null or v_budget<=0 then raise exception 'vsi_invalid_budget'; end if;
  select coalesce(sum(cost_usd),0) into v_spent from public.vsi_cost_events where workspace_id=p_workspace_id and occurred_at>=date_trunc('month',v_now at time zone 'UTC') at time zone 'UTC';
  select coalesce(sum(reservation_usd),0) into v_reserved from public.vsi_requests where workspace_id=p_workspace_id and status='pending';
  if v_spent+v_reserved+v_reserve>v_budget then return jsonb_build_object('error','workspace_budget'); end if;
  insert into public.vsi_requests(workspace_id,actor_user_id,conversation_id,request_id,question_hash,status,reservation_usd,lease_until)
   values(p_workspace_id,p_actor_user_id,c.id,(p_input->>'requestId')::uuid,p_input->>'questionHash','pending',v_reserve,v_now+interval '240 seconds')
   on conflict(workspace_id,actor_user_id,request_id) do update set status='pending',attempt=public.vsi_requests.attempt+1,
    reservation_usd=v_reserve,lease_until=v_now+interval '240 seconds',started_at=v_now returning * into r;
  return jsonb_build_object('state','reserved','request',to_jsonb(r));
 elsif p_action='settle' then
  select * into r from public.vsi_requests where id=(p_input->>'id')::uuid and workspace_id=p_workspace_id and actor_user_id=p_actor_user_id and conversation_id=c.id for update;
  if not found then raise exception 'vsi_request_not_found'; end if;
  if r.status='completed' then return jsonb_build_object('state','completed'); end if;
  if r.status<>'pending' or r.attempt<>(p_input->>'attempt')::integer then return jsonb_build_object('error','stale_attempt'); end if;
  v_spent:=coalesce((p_input->'usage'->>'estimatedCostUsd')::numeric,0);
  if v_spent<0 or v_spent>10 then raise exception 'vsi_invalid_cost'; end if;
  insert into public.vsi_cost_events(request_id,workspace_id,actor_user_id,attempt,occurred_at,cost_usd,usage_json)
   values(r.id,p_workspace_id,p_actor_user_id,r.attempt,r.started_at,v_spent,coalesce(p_input->'usage','{}'));
  update public.vsi_requests set status=case when coalesce(p_input->>'answer','')<>'' then 'completed' else 'failed' end,
    accepted_at=case when coalesce(p_input->>'answer','')<>'' then v_now else null end,
    cost_usd=cost_usd+v_spent,reservation_usd=0,lease_until=null,usage_json=usage_json||jsonb_build_array(coalesce(p_input->'usage','{}')) where id=r.id;
  if coalesce(p_input->>'answer','')<>'' then
   insert into public.vsi_exchanges(id,workspace_id,actor_user_id,conversation_id,user_message,answer,citations,remember_proposal,public_research_topics)
    values(r.id,p_workspace_id,p_actor_user_id,c.id,p_input->>'question',p_input->>'answer',coalesce(p_input->'citations','[]'),p_input->'rememberProposal',coalesce(p_input->'publicResearchTopics','[]'));
   update public.vsi_conversations set exchange_count=exchange_count+1,updated_at=v_now,
    title=case when exchange_count=0 and title='New chat' then left(p_input->>'question',80) else title end,
    context_summary=left(coalesce(p_input->>'summary',context_summary),8000) where id=c.id;
  end if;
  return jsonb_build_object('state','settled');
 elsif p_action='remember' then
  if v_role not in ('owner','admin','manager','staff') then raise exception 'vsi_note_permission' using errcode='42501'; end if;
  select * into e from public.vsi_exchanges where id=(p_input->>'exchangeId')::uuid and conversation_id=c.id for update;
  if not found or e.remember_proposal is null or e.remember_proposal='null'::jsonb then raise exception 'vsi_note_proposal_missing'; end if;
  if e.remember_proposal->>'content' is distinct from p_input->>'content' then raise exception 'vsi_note_proposal_changed'; end if;
  if e.saved_note_id is not null then
   select * into n from public.business_notes where id=e.saved_note_id and workspace_id=p_workspace_id for update;
  else
   select * into n from public.business_notes where workspace_id=p_workspace_id and release_channel=p_input->>'releaseChannel'
    and source_text_hash=p_input->>'sourceHash' and source_version=1 and deleted_at is null for update;
  end if;
  -- Existing notes keep their review/lifecycle state. Re-confirming a private
  -- proposal must never silently reopen a rejected, archived or approved note.
  if n.id is not null then
   if n.deleted_at is not null or n.status='archived' or n.evidence_lifecycle_status='archived' then
    return jsonb_build_object('error','note_archived');
   elsif n.status='rejected' then return jsonb_build_object('error','note_rejected');
   elsif n.status<>'review_required' then return jsonb_build_object('error','note_already_exists');
   end if;
   v_note:=n.id;
  end if;
  if v_note is null then
   insert into public.business_notes(workspace_id,author_user_id,original_note_text,source_text_hash,release_channel,status,evidence_lifecycle_status,
    extraction_json,source_spans_json,extracted_at,policy_version,validator_version)
    values(p_workspace_id,p_actor_user_id,p_input->>'content',p_input->>'sourceHash',p_input->>'releaseChannel','review_required','inactive',
    p_input->'extraction',p_input->'spans',v_now,'vsi_explicit_note_verbatim_v1','business_note_extraction_validator_v2') returning id into v_note;
  end if;
  update public.vsi_exchanges set saved_note_id=v_note where id=e.id;
  return jsonb_build_object('noteId',v_note);
 end if;
 raise exception 'vsi_unknown_action';
end;
$function$

CREATE OR REPLACE FUNCTION public.assert_document_extraction_authority_v1(p_workspace_id uuid, p_file_id uuid, p_job_id uuid, p_review_id uuid, p_artifact_fingerprint text, p_classification_fingerprint text, p_review_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_approved boolean;
begin
  if not public.is_workspace_member(p_workspace_id) then
    raise exception 'Workspace access denied.' using errcode = '42501';
  end if;
  v_approved := public.document_extraction_authority_is_approved_v1(
    p_workspace_id, p_file_id, p_job_id, p_review_id,
    p_artifact_fingerprint, p_classification_fingerprint, p_review_version
  );
  return jsonb_build_object(
    'eligible', v_approved,
    'reason', case when v_approved then 'eligible' else 'approval_missing_or_stale' end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.read_qbo_customer_accounting_authority_v1(p_connection_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c private.integration_connections; a private.qbo_accounting_authority_versions; session_id uuid;
  entity_name text; currency text;
begin
  if auth.role() is distinct from 'authenticated' then
    raise exception 'qbo_accounting_authority_denied' using errcode='42501'; end if;
  begin session_id:=(auth.jwt()->>'session_id')::uuid;
  exception when invalid_text_representation then
    raise exception 'qbo_accounting_authority_denied' using errcode='42501'; end;
  select * into c from private.integration_connections where id=p_connection_id
    and provider_key='quickbooks_online' and provider_environment='production';
  if not found then raise exception 'qbo_accounting_authority_denied' using errcode='42501'; end if;
  perform private.qbo_customer_require_owner_v1(auth.uid(),session_id,c.workspace_id,c.business_entity_id,true);
  select display_name,coalesce(reporting_currency,base_currency) into entity_name,currency
    from public.business_entities where id=c.business_entity_id and workspace_id=c.workspace_id;
  select * into a from private.qbo_accounting_authority_versions where workspace_id=c.workspace_id
    and business_entity_id=c.business_entity_id order by immutable_version desc limit 1;
  return jsonb_build_object('connectionId',c.id,'businessEntityId',c.business_entity_id,'businessEntityName',entity_name,
    'authorityId',a.id,'enabled',coalesce(a.enabled and a.connection_id=c.id
      and a.connection_generation=c.connection_generation and exists(select 1 from private.provider_entity_mappings m
        where m.id=a.mapping_id and m.status='active' and m.row_version=a.mapping_row_version),false),
    'effectiveFrom',case when a.id is null then null else
      to_char(a.effective_from at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') end,
    'currency',currency,'coverage','not_assessed');
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_document_extraction_file_authority_v1(p_workspace_id uuid, p_file_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_binding public.document_extraction_file_bindings%rowtype;
  v_job public.document_extraction_jobs%rowtype;
  v_review public.document_extraction_reviews%rowtype;
  v_is_service boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
begin
  if not v_is_service and not public.is_workspace_member(p_workspace_id) then
    raise exception 'Workspace access denied.' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.file_uploads file
    where file.id = p_file_id and file.workspace_id = p_workspace_id
      and file.deleted_at is null and file.archived_at is null
  ) then
    raise exception 'Active source file not found.' using errcode = 'P0002';
  end if;
  if not exists (
    select 1
    from public.document_extraction_file_bindings binding
    join public.document_extraction_jobs job
      on job.workspace_id = binding.workspace_id and job.id = binding.job_id
    where binding.workspace_id = p_workspace_id
      and binding.file_id = p_file_id
      and job.review_required
  ) then
    return jsonb_build_object('eligible', true, 'mode', 'existing_native_file_analysis', 'reason', 'existing_native_compatibility');
  end if;
  select * into v_binding
  from public.document_extraction_file_bindings
  where workspace_id = p_workspace_id and file_id = p_file_id and is_current
  order by created_at desc, id desc
  limit 1;
  if v_binding.id is null then
    return jsonb_build_object('eligible', false, 'mode', 'unapproved_document_extraction', 'reason', 'approval_missing_or_stale');
  end if;
  select * into v_job from public.document_extraction_jobs
  where id = v_binding.job_id and workspace_id = p_workspace_id;
  select * into v_review from public.document_extraction_reviews
  where workspace_id = p_workspace_id and job_id = v_job.id
    and review_version = v_job.required_review_version
  limit 1;
  if v_job.id is null or v_review.id is null or not public.document_extraction_authority_is_approved_v1(
    p_workspace_id,
    p_file_id,
    v_job.id,
    v_review.id,
    v_job.artifact_fingerprint,
    v_job.classification_fingerprint,
    v_job.required_review_version
  ) then
    return jsonb_build_object('eligible', false, 'mode', 'unapproved_document_extraction', 'reason', 'approval_missing_or_stale');
  end if;
  return jsonb_build_object(
    'eligible', true,
    'mode', 'reviewed_document_extraction',
    'reason', 'eligible',
    'job_id', v_job.id,
    'review_id', v_review.id,
    'artifact_fingerprint', v_job.artifact_fingerprint,
    'classification_fingerprint', v_job.classification_fingerprint,
    'review_version', v_job.required_review_version
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.qbo_customer_require_owner_v1(p_actor uuid, p_session uuid, p_workspace uuid, p_entity uuid, p_require_entitlement boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_expires timestamptz;
  v_subscription public.customer_subscriptions;
begin
  if p_actor is null or p_session is null or p_workspace is null or p_entity is null then
    raise exception 'qbo_customer_owner_denied' using errcode = '42501';
  end if;
  perform 1 from public.workspaces where id = p_workspace for share;
  if not found then raise exception 'qbo_customer_owner_denied' using errcode = '42501'; end if;
  select s.not_after into v_expires from auth.sessions s
    join auth.users u on u.id = s.user_id
    where s.id = p_session and s.user_id = p_actor and u.deleted_at is null
      and (u.banned_until is null or u.banned_until <= clock_timestamp())
    for share of s, u;
  if not found or (v_expires is not null and v_expires <= clock_timestamp()) then
    raise exception 'qbo_customer_session_denied' using errcode = '42501';
  end if;
  perform 1 from public.workspace_members m where m.workspace_id = p_workspace
    and m.user_id = p_actor and m.role = 'owner' and m.status = 'active' for share;
  if not found then raise exception 'qbo_customer_owner_denied' using errcode = '42501'; end if;
  perform 1 from public.business_entities e where e.workspace_id = p_workspace
    and e.id = p_entity and e.status = 'active' for share;
  if not found then raise exception 'qbo_customer_entity_denied' using errcode = '42501'; end if;
  if not p_require_entitlement then return; end if;
  select s.* into v_subscription from public.customer_subscriptions s
    where s.workspace_id = p_workspace and s.billing_provider = 'stripe'
    order by s.created_at desc, s.id desc limit 1 for share;
  if found then
    if v_subscription.manually_activated or v_subscription.status not in ('active','trialing')
      or v_subscription.current_period_end is null or v_subscription.current_period_end <= clock_timestamp()
      or v_subscription.stripe_customer_id is null or v_subscription.stripe_subscription_id is null then
      raise exception 'qbo_customer_entitlement_denied' using errcode = '42501';
    end if;
  elsif not exists (select 1 from public.workspaces w
      join public.customer_subscriptions s on s.workspace_id = w.id
      where w.id = p_workspace and w.manually_unlocked and s.billing_provider = 'manual'
        and s.manually_activated and s.status in ('active','trialing')) then
    raise exception 'qbo_customer_entitlement_denied' using errcode = '42501';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_business_note_evidence_boundaries()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth'
AS $function$
begin
  if new.workspace_id is distinct from old.workspace_id
    or new.author_user_id is distinct from old.author_user_id
    or new.original_note_text is distinct from old.original_note_text
    or new.original_file_id is distinct from old.original_file_id
    or new.source_text_hash is distinct from old.source_text_hash
    or new.source_version is distinct from old.source_version
    or new.release_channel is distinct from old.release_channel
    or new.created_at is distinct from old.created_at then
    raise exception 'Business Note source identity is immutable.' using errcode = '42501';
  end if;

  if coalesce(auth.role(), '') <> 'service_role' and (
    (old.status <> 'approved' and new.status = 'approved')
    or old.status = 'approved'
  ) then
    raise exception 'Business Note approval changes require the trusted server path.' using errcode = '42501';
  end if;

  return new;
end;
$function$
